-- =============================================================================
-- Seed Data: Web Thu Thap Du Lieu Lam Sang Suy Tim (MVP Nhom 1, 2, 6)
-- Generated deterministically from trace-table.xlsx
-- Contents: 2 sample users, 1 form_template, 2 form_version (v1.0 retired, v1.1 published),
--           16 form_section, 166 field_definition (140 mvp + 26 can_xac_nhan),
--           field_option, field_ai_module, and 280 form_field rows (121 archived + 159 current).
-- =============================================================================

BEGIN;

-- 1. Sample Users (2 roles: doctor & admin; non-production placeholder hashes)

-- 2. Form Template (1 MVP template)

-- 3. Form Version v1 (inserted as draft first, populated, then published cleanly)

-- 4. 8 Form Sections (section_code enum)

-- 5. 121 Field Definitions (95 mvp + 26 can_xac_nhan; 0 AI output codes)

-- 6. Field Options (single_choice & multi_choice choices)

-- 7. Field-to-AI-Module Readiness Mapping (Tier 4 metadata)

-- 8. Form Fields for v1 (all 121 catalog fields; can_xac_nhan hidden until confirmed)

-- 9. Publish v1 (after publishing, form_version v1 & its sections/fields become immutable)
UPDATE form_version
SET status = 'published',
    published_at = now(),
    published_by = 'fb65ae24-3f49-5dc1-8b5a-b08957ac449e',
    row_version = row_version + 1
WHERE id = '9965b491-5b78-5865-9220-53f7bc2c29fe';

-- 10. Initial Audit Log Entry for v1 publish

-- 11. HF form v1.1 seed
VALUES ('e661e6e4-057a-505c-a7a5-8c3032a9e6a1', 'e1682ea7-28dd-5846-93c0-8898d95229e5', 'hfmref','HFmrEF',5,true)
ON CONFLICT DO NOTHING;
ON CONFLICT (code) DO NOTHING;
DO $$ DECLARE old_id uuid; new_id uuid; sec record; BEGIN
SELECT id INTO old_id FROM form_version WHERE version_label='v1.0' AND form_template_id=(SELECT id FROM form_template WHERE code='heart_failure_intake') ORDER BY version_no LIMIT 1;
IF old_id IS NULL THEN RAISE EXCEPTION 'Seed v1.0 is required'; END IF;
IF EXISTS(SELECT 1 FROM form_version WHERE form_template_id=(SELECT form_template_id FROM form_version WHERE id=old_id) AND version_label='v1.1') THEN RETURN; END IF;
SELECT form_template_id,(SELECT max(version_no)+1 FROM form_version WHERE form_template_id=v.form_template_id),'v1.1','draft',id,'Biểu mẫu suy tim v1.1, phát hành khi khởi tạo.',created_by,
jsonb_build_object('di_ung_thuoc_can_quang', jsonb_build_object('storageLevel','visit_value','repeatGroup',null,'memberPath',null),'chan_doan_kieu_hinh_ef', jsonb_build_object('extraOptions',jsonb_build_array(jsonb_build_object('id','e661e6e4-057a-505c-a7a5-8c3032a9e6a1','optionCode','hfmref','labelVi','HFmrEF','displayOrder',5,'isActive',true)))) FROM form_version v WHERE id=old_id RETURNING id INTO new_id;
FOR sec IN SELECT * FROM form_section WHERE form_version_id=old_id LOOP
END LOOP;
SELECT new_id,ns.id,ff.field_definition_id,ff.display_order,ff.required_for_confirm,CASE WHEN fd.code IN ('cls_chuc_nang_gan','chan_doan_kieu_hinh_ef') THEN true ELSE ff.is_visible END,ff.is_readonly,ff.custom_label_vi,CASE WHEN fd.code='bmi' THEN 'Tự tính từ chiều cao và cân nặng; chỉ đọc.' ELSE ff.custom_help_text END
FROM form_field ff JOIN field_definition fd ON fd.id=ff.field_definition_id JOIN form_section os ON os.id=ff.form_section_id JOIN form_section ns ON ns.form_version_id=new_id AND ns.section_code=CASE WHEN fd.code IN ('chieu_cao_cm','can_nang_kg','bmi') THEN 'sinh_ton_kham'::section_code ELSE os.section_code END
WHERE ff.form_version_id=old_id AND fd.code NOT IN ('cls_don_vi','cls_thoi_diem','cls_ecg_thoi_diem','cls_sieu_am_tim_thoi_diem','cls_xquang_thoi_diem','thuoc_ghi_nhan','di_ung_adr');
SELECT new_id,fs.id,fd.id,1000+row_number() OVER(PARTITION BY fs.id ORDER BY fd.code),false,true,false FROM field_definition fd JOIN form_section fs ON fs.form_version_id=new_id AND fs.section_code=fd.section_code WHERE fd.code IN ('nhiet_do','ts_thuoc_la','ts_thuoc_la_ghi_chu','ts_thuoc_lao','ts_thuoc_lao_ghi_chu','ts_ruou_bia','ts_ruou_bia_ghi_chu','ts_chat_gay_nghien','ts_chat_gay_nghien_ghi_chu','ts_khac','ts_khac_ghi_chu','cls_cong_thuc_mau','cls_glucose','cls_hba1c','cls_ferritin','cls_tsat','cls_tsh','info_source','clinical_note','cls_result_unit','cls_result_measured_at','icd_code','icd_display','icd_role','medication_list_state','allergy_list_state','diagnosis_list_state','ha_nhip_tim','ha_phut_sau_doi_tu_the','thuoc_medicationgroup','thuoc_drugname','thuoc_activeingredient','thuoc_strength','thuoc_dose','thuoc_unit','thuoc_frequency','thuoc_route','thuoc_status','thuoc_startedat','diung_kind','diung_agentcategory','diung_allergen','diung_reaction','diung_severity','diung_recordedat');
END $$;

-- Retire the archived version before publishing, preserving the unique index.
UPDATE form_version
SET status = 'retired', row_version = row_version + 1
WHERE version_label = 'v1.0' AND status = 'published'
  AND form_template_id = (SELECT id FROM form_template WHERE code = 'heart_failure_intake');

UPDATE form_version
SET status = 'published', published_at = now(), published_by = created_by,
    row_version = row_version + 1
WHERE version_label = 'v1.1' AND status = 'draft'
  AND form_template_id = (SELECT id FROM form_template WHERE code = 'heart_failure_intake');

SELECT created_by, 'form_version_publish', 'form_version', id, 'success',
       '{"version_no": 2, "version_label": "v1.1", "seeded": true}'::jsonb
FROM form_version v
WHERE version_label = 'v1.1'
  AND form_template_id = (SELECT id FROM form_template WHERE code = 'heart_failure_intake')
  AND NOT EXISTS (SELECT 1 FROM audit_log a WHERE a.entity_id = v.id AND a.action = 'form_version_publish');

-- Assign any seeded patients to their creating doctor, retaining revoked history.
SELECT p.id, p.created_by, p.created_by, 'Seed patient creator'
FROM patient p JOIN app_user u ON u.id = p.created_by AND u.role = 'doctor'
WHERE NOT EXISTS (
  SELECT 1 FROM patient_care_assignment a
  WHERE a.patient_id = p.id AND a.doctor_user_id = p.created_by
);

COMMIT;
